/// A type's parameters in slot order (the engine's LOCK slots).
pub fn kind_params(kind: SoundKind) -> &'static [Spec] {
    match kind {
        SoundKind::Kick => &KICK_PARAMS,
        SoundKind::Snare => &SNARE_PARAMS,
        SoundKind::Hat => &HAT_PARAMS,
        SoundKind::Perc => &PERC_PARAMS,
        SoundKind::Bass => &BASS_PARAMS,
        SoundKind::Pad => &PAD_PARAMS,
        SoundKind::Lead => &LEAD_PARAMS,
        SoundKind::Pluck => &PLUCK_PARAMS,
    }
}

/// The type's output trim (InstrumentEntry.gain).
pub fn type_gain(kind: SoundKind) -> f64 {
    match kind {
        SoundKind::Kick => 0.565,
        SoundKind::Snare => 0.467,
        SoundKind::Hat => 1.783,
        SoundKind::Perc => 0.537,
        SoundKind::Bass => 0.557,
        SoundKind::Pad => 0.413,
        SoundKind::Lead => 0.948,
        SoundKind::Pluck => 1.105,
    }
}

